<template><div class="toast-container"><div v-for="t in toasts" :key="t.id" :class="['toast','toast-'+t.type]">{{ t.msg }}</div></div></template><script>export default { name: 'Toast', data(){return{toasts:[],id:1}}, methods:{show(msg,type='info',d=3000){const i=this.id++;this.toasts.push({id:i,msg,type});if(d>0)setTimeout(()=>this.toasts=this.toasts.filter(t=>t.id!==i),d)}} }</script>
